        add.accept("chain.supernaturalcraft.voice.demon.greet_ally.zealous.0", "Talk, meatsuit. Speak of service, and I will listen.");
        add.accept("chain.supernaturalcraft.voice.demon.greet_parley.ambitious.0", "Make it pay. Your proposal had better move me upward.");
        add.accept("chain.supernaturalcraft.voice.demon.greet_parley.loyal.0", "Make it pay. I will hear you without forgetting my allegiance.");
        add.accept("chain.supernaturalcraft.voice.demon.greet_parley.cruel.0", "Make it pay. I may listen. I will not learn compassion.");
