        add.accept("chain.supernaturalcraft.voice.demon.parley_refuse.cruel.0", "Bad offer. I would rather hear you beg than bargain.");
        add.accept("chain.supernaturalcraft.voice.demon.parley_refuse.cunning.0", "Bad offer. The risk is greater than anything you offer.");
