        add.accept("chain.supernaturalcraft.voice.demon.parley_refuse.zealous.0", "Bad offer. There can be no compromise with your cause.");
        add.accept("chain.supernaturalcraft.voice.demon.audience_greet.ambitious.0", "My court, my time. Show me how your service raises this throne.");
        add.accept("chain.supernaturalcraft.voice.demon.audience_greet.loyal.0", "My court, my time. Speak. A throne owes its faithful a hearing.");
        add.accept("chain.supernaturalcraft.voice.demon.audience_greet.cruel.0", "My court, my time. Approach. I enjoy seeing petitioners tremble.");
        add.accept("chain.supernaturalcraft.voice.demon.audience_greet.cunning.0", "My court, my time. Every request has a consequence. Choose yours.");
        add.accept("chain.supernaturalcraft.voice.demon.audience_greet.proud.0", "My court, my time. You stand before my throne. Remember that.");
        add.accept("chain.supernaturalcraft.voice.demon.audience_greet.zealous.0", "My court, my time. Ask only what strengthens the cause.");
        add.accept("chain.supernaturalcraft.voice.demon.coward.ambitious.0", "No spine, then. Your refusal has raised me at your expense.");
        add.accept("chain.supernaturalcraft.voice.demon.coward.loyal.0", "No spine, then. You failed the rules you claimed to honour.");
        add.accept("chain.supernaturalcraft.voice.demon.coward.cruel.0", "No spine, then. I wanted your screams. Your silence will do.");
        add.accept("chain.supernaturalcraft.voice.demon.coward.cunning.0", "No spine, then. You chose safety, and paid more than you knew.");
        add.accept("chain.supernaturalcraft.voice.demon.coward.proud.0", "No spine, then. You denied me a contest and shamed yourself.");
        add.accept("chain.supernaturalcraft.voice.demon.coward.zealous.0", "No spine, then. The cause has no use for a shrinking heart.");
        add.accept("chain.supernaturalcraft.voice.angel.sight_foe.ambitious.0", "By the Throne: Your defeat will carry me higher.");
        add.accept("chain.supernaturalcraft.voice.angel.sight_foe.loyal.0", "By the Throne: I guard the charge I was given.");
